package com.shengxu.controller;
import com.shengxu.dto.*; import com.shengxu.dto.MusicDtos.*; import com.shengxu.entity.MusicTask; import com.shengxu.service.MusicTaskService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/music-tasks") public class MusicTaskController {private final MusicTaskService s;public MusicTaskController(MusicTaskService s){this.s=s;}@PostMapping public ResponseEntity<ApiResponse<TaskView>> create(Authentication a,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody CreateTask in){MusicTask t=s.create((Long)a.getPrincipal(),key,in);return ResponseEntity.status(HttpStatus.ACCEPTED).body(ApiResponse.ok(s.get((Long)a.getPrincipal(),t.getId())));}@GetMapping public ApiResponse<PageView<TaskView>> list(Authentication a,@RequestParam(defaultValue="1") long page,@RequestParam(defaultValue="20") long pageSize){return ApiResponse.ok(s.list((Long)a.getPrincipal(),page,pageSize));}@GetMapping("/{id}") public ApiResponse<TaskView> get(Authentication a,@PathVariable Long id){return ApiResponse.ok(s.get((Long)a.getPrincipal(),id));}}

